const expect = require('chai').expect;

const { SourceMapConsumer } = require('../../dist/utils/source-map');

// Real sourcemap generated by tsc for:
//   export function greet(name: string): string {
//     const message = `Hello, ${name}!`;
//     return message.toUpperCase();
//   }
//
//   export function add(a: number, b: number): number {
//     return a + b;
//   }
const SAMPLE_MAP = {
  version: 3,
  file: 'sample.js',
  sourceRoot: '',
  sources: ['../sample.ts'],
  names: [],
  mappings:
    ';;AAAA,sBAGC;AAED,kBAEC;AAPD,SAAgB,KAAK,CAAC,IAAY;IAChC,MAAM,OAAO,GAAG,UAAU,IAAI,GAAG,CAAC;IAClC,OAAO,OAAO,CAAC,WAAW,EAAE,CAAC;AAC/B,CAAC;AAED,SAAgB,GAAG,CAAC,CAAS,EAAE,CAAS;IACtC,OAAO,CAAC,GAAG,CAAC,CAAC;AACf,CAAC',
  sourcesContent: [
    'export function greet(name: string): string {\n' +
      '  const message = `Hello, ${name}!`;\n' +
      '  return message.toUpperCase();\n' +
      '}\n' +
      '\n' +
      'export function add(a: number, b: number): number {\n' +
      '  return a + b;\n' +
      '}\n'
  ]
};

describe('utils : source-map', () => {
  describe('SourceMapConsumer', () => {
    it('accepts a raw JSON string or a parsed object', () => {
      const fromString = new SourceMapConsumer(JSON.stringify(SAMPLE_MAP));
      const fromObject = new SourceMapConsumer(SAMPLE_MAP);
      const expected = {
        source: '../sample.ts',
        line: 4,
        column: 1,
        name: null
      };
      expect(fromString.originalPositionFor({ line: 8, column: 14 })).to.eql(
        expected
      );
      expect(fromObject.originalPositionFor({ line: 8, column: 14 })).to.eql(
        expected
      );
    });

    it('maps generated positions back to original source positions', () => {
      const consumer = new SourceMapConsumer(SAMPLE_MAP);

      // generated line 3 col 14 -> greet() declaration (ts line 1)
      expect(consumer.originalPositionFor({ line: 3, column: 14 })).to.eql({
        source: '../sample.ts',
        line: 1,
        column: 0,
        name: null
      });

      // generated line 8 col 14 -> `const message` (ts line 4)
      expect(consumer.originalPositionFor({ line: 8, column: 14 })).to.eql({
        source: '../sample.ts',
        line: 4,
        column: 1,
        name: null
      });

      // generated line 10 col 20 -> `return a + b` (ts line 7)
      expect(consumer.originalPositionFor({ line: 10, column: 20 })).to.eql({
        source: '../sample.ts',
        line: 7,
        column: 15,
        name: null
      });

      // generated line 11 col 10 -> closing brace of add() (ts line 8)
      expect(consumer.originalPositionFor({ line: 11, column: 10 })).to.eql({
        source: '../sample.ts',
        line: 8,
        column: 1,
        name: null
      });
    });

    it('uses greatest-lower-bound column matching within a line', () => {
      const consumer = new SourceMapConsumer(SAMPLE_MAP);
      const position = { line: 8, column: 40 };
      const glb = consumer.originalPositionFor(position);
      const exact = consumer.originalPositionFor({ line: 8, column: 14 });
      expect(glb).to.eql(exact);
    });

    it('returns nulls for unmapped lines and out-of-range positions', () => {
      const consumer = new SourceMapConsumer(SAMPLE_MAP);
      const nullPosition = {
        source: null,
        line: null,
        column: null,
        name: null
      };

      // generated line 1 has no mappings
      expect(consumer.originalPositionFor({ line: 1, column: 0 })).to.eql(
        nullPosition
      );
      // beyond the last generated line
      expect(consumer.originalPositionFor({ line: 99, column: 0 })).to.eql(
        nullPosition
      );
    });

    it('returns source content when available', () => {
      const consumer = new SourceMapConsumer(SAMPLE_MAP);
      const content = consumer.sourceContentFor('../sample.ts', true);
      expect(content).to.contain('export function greet');
      expect(content).to.contain('return a + b;');
    });

    it('returns null or throws for missing sources depending on flag', () => {
      const consumer = new SourceMapConsumer(SAMPLE_MAP);
      expect(consumer.sourceContentFor('missing.ts', true)).to.equal(null);
      expect(() => consumer.sourceContentFor('missing.ts')).to.throw(
        /not in the SourceMap/
      );
    });

    it('handles maps without sourcesContent or names', () => {
      const map = { ...SAMPLE_MAP };
      delete map.sourcesContent;
      const consumer = new SourceMapConsumer(map);
      expect(consumer.sourceContentFor('../sample.ts', true)).to.equal(null);
      expect(
        consumer.originalPositionFor({ line: 8, column: 14 }).name
      ).to.equal(null);
    });

    it('handles empty mappings', () => {
      const consumer = new SourceMapConsumer({
        version: 3,
        sources: [],
        names: [],
        mappings: ''
      });
      expect(consumer.originalPositionFor({ line: 1, column: 0 })).to.eql({
        source: null,
        line: null,
        column: null,
        name: null
      });
    });

    it('destroy is a safe no-op', () => {
      const consumer = new SourceMapConsumer(SAMPLE_MAP);
      expect(() => consumer.destroy()).to.not.throw();
    });
  });
});
